import React, { useEffect, useState } from "react";

// results/index.json (generated by scripts/build_results_index.py; copied into the site by the Pages workflow)
export const RESULTS = "./results";

export interface GroupStat { n_doors: number; n_episodes: number; n_success: number; success_rate: number; doors_solved: number; doors_solved_any: number; damage_rate: number; mean_time_to_pass_s: number | null }
export interface ResultEntry {
  file: string; policy: string; description: string; embodiment: string; policy_class?: string; extra?: Record<string, any>;
  simulator: string; simulator_version?: string | null; tier: string; date: string; label?: string; commit?: string | null; dataset_version?: string | null;
  n_doors_total?: number; n_doors: number; seeds: number[]; scenarios: string[]; randomize?: boolean; time_budget_s?: any; wall_time_s?: number; mean_wall_s?: number | null; host?: string | null;
  leaderboard: boolean; doors_solved: number; doors_solved_any: number; n_episodes: number; n_success: number; success_rate: number; damage_rate: number;
  mean_time_to_pass_s: number | null; median_time_to_pass_s: number | null; outcomes: Record<string, number>;
  by_family: Record<string, GroupStat>; by_task: Record<string, GroupStat>; by_difficulty: Record<string, GroupStat>; by_lock_state: Record<string, GroupStat>; by_scenario: Record<string, GroupStat>;
  doors: Record<string, [number, number]>;   // door id -> [n_success, n_episodes] in the default scenario
}
export interface ResultsIndex { schema_version: string; generated: string; n_doors_total: number; results: ResultEntry[] }

let cache: ResultsIndex | null | undefined;      // undefined = not fetched, null = missing
let pending: Promise<ResultsIndex | null> | null = null;
const listeners = new Set<(r: ResultsIndex | null) => void>();

export function loadResultsIndex(): Promise<ResultsIndex | null> {
  if (cache !== undefined) return Promise.resolve(cache);
  if (!pending) {
    pending = fetch(`${RESULTS}/index.json`).then((r) => (r.ok ? r.json() : null)).catch(() => null).then((r) => {
      cache = r as ResultsIndex | null;
      listeners.forEach((l) => l(cache!));
      return cache!;
    });
  }
  return pending;
}

/** Shared, fetched-once results index (null when results/index.json is absent, e.g. a fresh clone). */
export function useResultsIndex(): ResultsIndex | null | undefined {
  const [idx, setIdx] = useState<ResultsIndex | null | undefined>(cache);
  useEffect(() => {
    if (cache !== undefined) { setIdx(cache); return; }
    listeners.add(setIdx);
    loadResultsIndex();
    return () => { listeners.delete(setIdx); };
  }, []);
  return idx;
}

export function outcomeClass(s: [number, number] | undefined): string {
  if (!s || s[1] === 0) return "none";
  if (s[0] === s[1]) return "ok";
  if (s[0] === 0) return "bad";
  return "part";
}

/** Small per-door chips: one per leaderboard policy, "policy n/N" (successful seeds / seeds) in the default scenario. */
export function BaselineBadges({ id, compact = true }: { id: string; compact?: boolean }) {
  const idx = useResultsIndex();
  if (!idx) return null;
  const rows = idx.results.filter((r) => r.leaderboard);
  if (!rows.length) return null;
  return (
    <>
      {rows.map((r) => {
        const s = r.doors[id];
        const cls = outcomeClass(s);
        const txt = s ? `${s[0]}/${s[1]}` : "–";
        const title = s ? `${r.policy}: ${s[0]} of ${s[1]} seed(s) successful (${r.simulator} ${r.tier}, ${r.date})` : `${r.policy}: not evaluated`;
        return <span key={r.file} className={`chip res ${cls}`} title={title}>{compact ? r.policy.replace(/_/g, " ") : r.policy} {txt}</span>;
      })}
    </>
  );
}
